/* @autogenerated */
import { fakeAsync, tick } from '@angular/core/testing';
import { BehaviorSubject } from 'rxjs';
import { LocalRouteStateService } from './local-route-state.service';

describe('LocalRouteStateService', () => {
  it('merges inner and outer query params on go', () => {
    const router = { navigate: jasmine.createSpy('navigate') } as any;
    const queryParams$ = new BehaviorSubject({ view: 'a', other: '1' });
    const route = {
      snapshot: { queryParams: queryParams$.value },
      queryParams: queryParams$.asObservable(),
    } as any;

    const service = new LocalRouteStateService(router, route);
    const bind = service.bind(['view']);

    bind.go({ view: 'b' });
    expect(router.navigate).toHaveBeenCalledWith([], {
      queryParams: { other: '1', view: 'b' },
      queryParamsHandling: 'replace',
    });
  });

  it('watches changes and clears params on unsubscribe', fakeAsync(() => {
    const router = { navigate: jasmine.createSpy('navigate') } as any;
    const queryParams$ = new BehaviorSubject({ view: 'a', other: '1' });
    const route = {
      snapshot: { queryParams: queryParams$.value },
      queryParams: queryParams$.asObservable(),
    } as any;

    const service = new LocalRouteStateService(router, route);
    const bind = service.bind(['view']);
    const received: any[] = [];

    const sub = bind.watch().subscribe((value) => received.push(value));
    tick();

    queryParams$.next({ view: 'b', other: '1' });
    tick();

    expect(received).toEqual([{ view: 'a' }, { view: 'b' }]);

    sub.unsubscribe();

    expect(router.navigate).toHaveBeenCalledWith([], {
      queryParams: { other: '1' },
      queryParamsHandling: 'replace',
    });
  }));
});
